Perfecto. Veamos el código:

```c
printf("Cantidad de maquinas: ");
scanf("%d", &nMaquinas);
int totalGeneral = 0;
int contMaquina = 1;

while (contMaquina <= nMaquinas) {
    printf("\n--- Maquina #%d ---\n", contMaquina);
    printf("Cantidad de turnos: ");
    scanf("%d", &nTurnos);

    int totalMaquina = 0;
    int contTurno = 1;

    while (contTurno <= nTurnos) {
        int piezas;
        printf("  Piezas producidas en turno #%d: ", contTurno);
        scanf("%d", &piezas);
        totalMaquina = totalMaquina + piezas;
        contTurno = contTurno + 1;
    }

    printf("Total producido por maquina #%d: %d piezas\n", contMaquina, totalMaquina);
    totalGeneral = totalGeneral + totalMaquina;
    contMaquina = contMaquina + 1;
}
printf("Produccion total de la fabrica: %d piezas\n", totalGeneral);
```

